'use strict';

// MODULES //

var tape = require( 'tape' );
var oneTo = require( '@stdlib/array/one-to' );
var real = require( '@stdlib/complex/float64/real' );
var imag = require( '@stdlib/complex/float64/imag' );
var ndarray = require( '@stdlib/ndarray/ctor' );
var untilEach = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof untilEach, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function invokes a callback for each element in a 1-dimensional ndarray until the predicate returns a truthy value', function test( t ) {
	var expected;
	var values;
	var x;

	x = ndarray( 'float64', oneTo( 8, 'float64' ), [ 4 ], [ 1 ], 0, 'row-major' );

	values = [];
	untilEach( [ x ], predicate, fcn );

	expected = [ 1.0, 2.0 ];
	t.deepEqual( values, expected, 'returns expected value' );

	t.end();

	function predicate( v ) {
		return v >= 3.0;
	}

	function fcn( v ) {
		values.push( v );
	}
});

tape( 'the function invokes a callback for each element in a 1-dimensional ndarray until the predicate returns a truthy value (negative strides)', function test( t ) {
	var expected;
	var values;
	var x;

	x = ndarray( 'float64', oneTo( 8, 'float64' ), [ 4 ], [ -1 ], 3, 'row-major' );

	values = [];
	untilEach( [ x ], predicate, fcn );

	expected = [ 4.0, 3.0 ];
	t.deepEqual( values, expected, 'returns expected value' );

	t.end();

	function predicate( v ) {
		return v <= 2.0;
	}

	function fcn( v ) {
		values.push( v );
	}
});

tape( 'the function invokes a callback for each element in a 1-dimensional ndarray until the predicate returns a truthy value (accessors)', function test( t ) {
	var expected;
	var values;
	var x;

	x = ndarray( 'complex128', oneTo( 8, 'complex128' ), [ 4 ], [ 1 ], 0, 'row-major' );

	values = [];
	untilEach( [ x ], predicate, fcn );

	expected = [
		[ 1.0, 0.0 ],
		[ 2.0, 0.0 ]
	];
	t.deepEqual( values, expected, 'returns expected value' );

	t.end();

	function predicate( v ) {
		return real( v ) >= 3.0;
	}

	function fcn( v ) {
		values.push( [ real( v ), imag( v ) ] );
	}
});

tape( 'the function supports specifying the callback execution context', function test( t ) {
	var expected;
	var indices;
	var values;
	var arrays;
	var ctx;
	var x;

	x = ndarray( 'float64', oneTo( 8, 'float64' ), [ 4 ], [ 1 ], 0, 'row-major' );

	indices = [];
	values = [];
	arrays = [];

	ctx = {};
	untilEach( [ x ], predicate, fcn, ctx );

	expected = [ 1.0, 2.0 ];
	t.deepEqual( values, expected, 'returns expected value' );

	expected = [ [ 0 ], [ 1 ] ];
	t.deepEqual( indices, expected, 'returns expected value' );

	expected = [ x, x ];
	t.deepEqual( arrays, expected, 'returns expected value' );

	t.end();

	function predicate( v ) {
		return v >= 3.0;
	}

	function fcn( v, idx, arr ) {
		t.strictEqual( this, ctx, 'returns expected context' ); // eslint-disable-line no-invalid-this
		values.push( v );
		indices.push( idx );
		arrays.push( arr );
	}
});

tape( 'the function supports specifying the callback execution context (accessors)', function test( t ) {
	var expected;
	var indices;
	var values;
	var arrays;
	var ctx;
	var x;

	x = ndarray( 'complex128', oneTo( 8, 'complex128' ), [ 4 ], [ 1 ], 0, 'row-major' );

	indices = [];
	values = [];
	arrays = [];

	ctx = {};
	untilEach( [ x ], predicate, fcn, ctx );

	expected = [
		[ 1.0, 0.0 ],
		[ 2.0, 0.0 ]
	];
	t.deepEqual( values, expected, 'returns expected value' );

	expected = [ [ 0 ], [ 1 ] ];
	t.deepEqual( indices, expected, 'returns expected value' );

	expected = [ x, x ];
	t.deepEqual( arrays, expected, 'returns expected value' );

	t.end();

	function predicate( v ) {
		return real( v ) >= 3.0;
	}

	function fcn( v, idx, arr ) {
		t.strictEqual( this, ctx, 'returns expected context' ); // eslint-disable-line no-invalid-this
		values.push( [ real( v ), imag( v ) ] );
		indices.push( idx );
		arrays.push( arr );
	}
});
